INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66394801', 66394801, 'analyze_legacy', 'Aceh', 'central', 'Sekretariat DPR Aceh', 'Pemeliharaan Alat Kedokteran Umum dan Kedokteran Gigi', 'Jasa Lainnya', 'Pengadaan Langsung', 'Aceh, Banda Aceh (Kota)', 15000000, 'January 2026', 'APBD', 1, 1, '1 tahun x0.137254894784058', 'KAK', 'KAK', 15000000, 'high', 'Pengadaan pemeliharaan alat kedokteran umum dan kedokteran gigi oleh sekretariat legislatif tampak tidak selaras dengan fungsi utama kelembagaan yang bersifat administratif dan pendukung kedewanan. Dari judul item, kebutuhan ini berindikasi kuat tidak relevan sehingga seluruh nilai pengadaan patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2711304);
