INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66358922', 66358922, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 3037000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Snack Rapat CPIB Kapal JAWA BARAT 2. Makan Rapat CPIB Kapal JAWA BARAT 3. Bahan Pendukung Kegiatan 4. Banner Kegiatan CPIB Kapal', '1. Konsumsi Rapat (Snack & Makan) • Volume: 15 Orang . • Pagu Anggaran: Snack @Rp22.000 | Makan @Rp54.000 (Sesuai SBM 2026 Wilayah Jawa Barat). • Ketentuan Teknis: Snack: Terdiri dari minimal 3 jenis kudapan (kombinasi rasa manis dan asin) serta air mineral gelas (minimal 220ml). Diutamakan menggunakan kemasan kotak yang ramah lingkungan. Makan: Menu prasmanan atau nasi kotak yang terdiri dari: Nasi putih, 1 jenis protein hewani (ikan/ayam/daging), 1 jenis sayuran, pelengkap (kerupuk/sambal), buah potong, dan air mineral botol (minimal 330ml). Kualitas: Makanan harus segar, halal, bersih, dan disajikan maksimal 30 menit sebelum waktu istirahat dimulai. Layanan: Penyedia wajib menyediakan peralatan makan dan petugas kebersihan selama acara berlangsung (jika metode prasmanan). 2. Bahan Pendukung Kegiatan • Volume: 15 Souvenir. • Lingkup Pekerjaan: Penyediaan paket alat tulis atau bahan operasional peserta (Seminar Kit) yang meliputi: Buku catatan/Block note dan Pulpen. Map dokumen/Folder kegiatan untuk materi CPIB. Tanda pengenal peserta (Name tag). Modul/Handout materi sosialisasi mengenai standar penanganan ikan di atas kapal. Bahan praktis pendukung lainnya (seperti masker atau sarung tangan sekali pakai untuk peragaan penanganan ikan). 3. Banner Kegiatan CPIB Kapal • Volume: 2 Banner. • Ketentuan Teknis: Material: Bahan Flexy High Resolution (minimal 340 gsm) atau bahan sejenis yang tahan cuaca. Ukuran: Sesuai kebutuhan lokasi (3x1 meter untuk backdrop atau 0,6x1,6 meter untuk X-Banner). Desain: Mencantumkan logo instansi, judul kegiatan "CPIB Kapal", nama wilayah di Jawa Barat, serta elemen grafis yang edukatif tentang sanitasi kapal. Finishing: Dilengkapi mata ayam (lubang pengikat) di setiap sudut atau rangka penyangga (untuk X-Banner).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2712001);
