INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66359697', 66359697, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Belanja Modal Peralatan dan Mesin berupa Alat Music Modern/Band pada ditjen kekayaan intelektual dki jakarta T.A 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 180000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '14 Hari', 'Musik berfungsi sebagai sarana untuk meningkatkan motivasi, fokus, serta mengurangi tingkat stres di lingkungan kerja. Fasilitas ini mendukung mood positif yang berkontribusi pada interaksi tim yang lebih kooperatif. Peralatan musik sangat penting untuk menunjang kegiatan taktis dan operasional, seperti pengisian musik pada upacara resmi, pertemuan strategis, atau sebagai sarana komunikasi internal dan publik. pengadaan peralatan musik di instansi pemerintah didorong oleh kebutuhan operasional organisasi untuk meningkatkan kinerja pegawai dan pemenuhan fungsi pelayanan publik. Secara strategis, pengadaan ini bertujuan untuk menciptakan lingkungan kerja yang mendukung produktivitas serta memperkuat identitas budaya instansi melalui sarana kesenian memiliki peralatan musik secara mandiri membantu organisasi memenuhi target kinerja tanpa ketergantungan pada pihak luar, yang pada akhirnya menunjang kelancaran operasional harian kantor. Pengadaan Belanja Modal Peralatan dan Mesin berupa Alat Music Modern/Band ini bertujuan untuk menciptakan lingkungan kerja yang mendukung produktivitas serta memperkuat identitas budaya instansi melalui sarana kesenian pada Direktorat Jenderal Kekayaan Intelektual. Oleh karena itu dibutuhkan pengadaan peralatan tersebut demi kelancaran kegiatan serta kelengkapan sarana dan prasarana di kantor Direktorat Jenderal Kekayaan Intelektual', 'Satu Set Alat Band Modern', 180000000, 'absurd', 'Pengadaan satu set alat musik modern/band untuk unit kerja administratif bidang kekayaan intelektual tampak tidak selaras dengan fungsi inti pelayanan publik. Uraian justifikasi lebih menekankan peningkatan mood, pengurangan stres, dan sarana kesenian internal, yang umumnya bukan kebutuhan prioritas belanja modal pemerintah. Nilai anggaran penuh berpotensi merupakan pemborosan karena manfaat operasional esensial tidak terlihat kuat dari konteks yang tersedia.', NULL, NULL, 4, 1, 1, 1, 1, 2712060);
