INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66363036', 66363036, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Pemeliharaan Gedung dan Bangunan', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 137693000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Pemeliharaan Halaman Gedung/Bangunan Kantor (Jawa Barat) ( 2976, M2); 2. Penataan Ruang Rapat ( 1, PKT, @ 25000000 ); 3. Pemeliharaan Gedung/Bangunan Kantor Bertingkat (Jawa Barat) ( 394, M2, ); 54 Pemeliharaan Gedung/Bangunan Kantor Tidak Bertingkat (Jawa Barat) ( 100, M2,);', '1. Pemeliharaan Halaman Gedung/Bangunan (Jawa Barat) Volume: 2.976 M² Lingkup Pekerjaan: Perawatan Taman: Pemotongan rumput, pemangkasan tanaman pagar, dan pembersihan gulma secara berkala. Kebersihan Area Luar: Pembersihan selokan/drainase di area halaman, penyapuan paving block/area parkir, dan pembuangan sampah halaman ke TPS. Estetika: Perapian tanaman agar tidak menghalangi rambu atau jalur pejalan kaki. Ketentuan: Pekerjaan dilakukan secara rutin bulanan untuk menjaga kebersihan dan estetika area luar kantor. 2. Pemeliharaan Gedung Kantor Bertingkat & Tidak Bertingkat Volume Bertingkat: 394 M² | Tidak Bertingkat: 100 M² Lingkup Pekerjaan: Arsitektural: Pengecatan ulang dinding yang kusam/berlumut, perbaikan plafon yang rusak/bocor, dan penggantian keramik lantai yang pecah. Struktural: Pengecekan talang air untuk mencegah kebocoran saat hujan deras. Mekanis: Pengecekan engsel pintu, kunci, dan jendela agar berfungsi dengan baik. Standar Harga: Mengacu pada Standar Biaya Masukan (SBM) 2026 wilayah Jawa Barat untuk pemeliharaan gedung/bangunan. 3. Penataan Ruang Rapat Volume: Pagu: Rp25.000.000,- Lingkup Pekerjaan: Interior: Pemasangan backdrop dinding, penggantian gorden/blind, atau pemasangan peredam suara jika diperlukan. Fasilitas: Penataan meja rapat (U-shape/Classroom) dan pengecekan jalur kabel data/listrik agar tertanam rapi (under table management). Estetika: Penambahan elemen dekoratif (tanaman indoor/lukisan) dan pengaturan tata cahaya (lighting) untuk mendukung kegiatan rapat virtual (Vicon).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2716351);
