INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66362243', 66362243, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 4939000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Perlengkapan Sertifikasi ( 1, PKT, @ 1700000 ); 2. Makan Rapat CBIB JAWA BARAT ( 20, OK, @ 54000 ); 3. Banner Kegiatan CBIB Pembudidaya Ikan ( 2, BH, ); 4. Bahan Pendukung Kegiatan CBIB Pembudidaya Ikan ( 1, PKT, ); 5. Snack Rapat CBIB JAWA BARAT ( 20, OK, @ 22000 );', '1. Konsumsi Rapat (Makan & Snack) • Volume: 20 Orang (20 OK). • Pagu Anggaran: Makan @Rp54.000 | Snack @Rp22.000 (Sesuai SBM 2026 Jawa Barat). • Ketentuan Teknis: Makan: Menu nasi kotak/prasmanan yang terdiri dari Nasi Putih, Lauk Utama (Ikan/Ayam), Lauk Pendamping (Tahu/Tempe), Sayuran, Buah, dan Air Mineral Botol (min. 330ml). Snack: Minimal 3 jenis kudapan (manis & asin) serta Air Mineral Gelas (min. 220ml). Kualitas: Makanan harus segar, halal, dan disajikan dengan kemasan yang bersih serta ramah lingkungan. 2. Perlengkapan Sertifikasi • Volume: Alat Tulis Kantor. • Lingkup Pekerjaan: Penyediaan dokumen dan perangkat administrasi untuk mendukung proses pengajuan sertifikasi CBIB, meliputi: Map jepit/Folder khusus dokumen sertifikasi. Pencetakan formulir pendaftaran dan kuisioner penilaian mandiri (self-assessment) CBIB. Alat tulis kantor (ATK) pendukung administrasi sertifikasi. 3. Bahan Pendukung Kegiatan CBIB • Volume: 20 Souvenir. • Lingkup Pekerjaan: Penyediaan Seminar Kit atau materi edukasi untuk 40 peserta, meliputi: Buku panduan/Modul Teknis CBIB terbaru tahun 2026. Buku catatan (Notes) dan Pulpen. Tas seminar/Goodie bag berbahan kain. Tanda pengenal peserta (ID Card). 4. Banner Kegiatan CBIB • Volume: 2 Banner. • Ketentuan Teknis: Material: Cetak High Resolution pada bahan Flexy minimal 340 gsm. Ukuran: Sesuai kebutuhan lokasi (Contoh: 3x1 meter atau 4x1 meter). Desain: Wajib mencantumkan Logo Instansi, Judul Kegiatan "Sosialisasi CBIB", Tahun 2026, dan pesan edukatif mengenai budidaya ikan yang aman dan higienis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2716787);
